/**
 * Scroll-triggered entrance animations.
 *
 * Returns `[ref, played]`. Attach the ref; render the un-played styles while
 * `played` is false and the final styles once it flips. React handles the rest,
 * so — unlike the original, which wrote transition strings onto elements by
 * hand — the animated state stays visible in the component that owns it.
 *
 * One shared IntersectionObserver serves the whole page. Elements are
 * unobserved the moment they first intersect: these are entrance animations,
 * they never replay.
 */

import { useEffect, useRef, useState } from 'react';
import { useIntro } from '../context/IntroProvider.jsx';

/** element -> callback, so one observer can dispatch to many hooks. */
const callbacks = new WeakMap();

let observer = null;

function getObserver() {
  if (observer) return observer;

  observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;

        // Entrance only — stop watching immediately.
        observer.unobserve(entry.target);
        callbacks.get(entry.target)?.();
        callbacks.delete(entry.target);
      });
    },
    {
      root: null,
      // Trigger slightly before the element reaches the bottom edge, so the
      // animation is already underway by the time it is comfortably in view.
      rootMargin: '0px 0px -8% 0px',
      threshold: 0,
    },
  );

  return observer;
}

/**
 * @param {object}  [options]
 * @param {boolean} [options.gate] Hold until the loader finishes. Use for
 *   anything visible on first paint — it would otherwise animate behind the
 *   loader and be finished before the visitor sees it.
 * @returns {[import('react').RefObject<HTMLElement>, boolean]}
 */
export function useReveal({ gate = false } = {}) {
  const ref = useRef(null);
  const [intersected, setIntersected] = useState(false);
  const { introReady } = useIntro();

  useEffect(() => {
    const element = ref.current;
    if (!element || intersected) return undefined;

    const activeObserver = getObserver();
    callbacks.set(element, () => setIntersected(true));
    activeObserver.observe(element);

    return () => {
      activeObserver.unobserve(element);
      callbacks.delete(element);
    };
  }, [intersected]);

  // A gated element that is already on screen simply waits here: `intersected`
  // is true but `played` stays false until the loader releases the gate.
  const played = intersected && (!gate || introReady);

  return [ref, played];
}

/**
 * Builds the inline style for a block reveal.
 *
 * @param {boolean} played
 * @param {object}  offsets      Starting offsets, e.g. { y: 20, o: 0, scale: 0.96 }
 * @param {object}  timing       { delay, duration, ease }
 * @param {number}  [finalOpacity] Resting opacity. The hero watermark rests at
 *                                 0.4, not 1.
 */
export function buildRevealStyle(played, offsets = {}, timing = {}, finalOpacity = 1) {
  const { delay = 0, duration = 800, ease } = timing;

  const transition =
    `transform ${duration}ms ${ease} ${delay}ms, opacity ${duration}ms ${ease} ${delay}ms`;

  if (played) {
    return { transform: 'none', opacity: finalOpacity, transition };
  }

  let transform = '';
  if (offsets.y !== undefined || offsets.x !== undefined) {
    transform += `translate(${offsets.x || 0}px,${offsets.y || 0}px)`;
  }
  if (offsets.scale !== undefined) {
    transform += ` scale(${offsets.scale})`;
  }

  return {
    transform: transform || undefined,
    opacity: offsets.o !== undefined ? offsets.o : undefined,
    transition,
    // Hints the compositor to promote this to its own layer before the
    // transition starts, avoiding a first-frame stutter.
    willChange: 'transform, opacity',
  };
}
