/**
 * Runs a handler when Escape is pressed, while `active` is true.
 *
 * Both overlays need this; the listener is only attached while the overlay is
 * open so a closed panel isn't sitting on a global keydown handler.
 */

import { useEffect } from 'react';

export function useEscapeKey(active, handler) {
  useEffect(() => {
    if (!active) return undefined;

    function onKeyDown(event) {
      if (event.key === 'Escape') handler();
    }

    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [active, handler]);
}
