/**
 * A single portfolio card.
 *
 * One hover group drives two springs at once: the card lifts and scales while
 * its corner badge rotates 45° — the arrow swings from "up-right" to "right".
 */

import HoverGroup from '../common/HoverGroup.jsx';
import SpringHover from '../common/SpringHover.jsx';
import Chip from '../common/Chip.jsx';
import Icon from '../icons/Icon.jsx';

export default function WorkCard({ work }) {
  return (
    <HoverGroup as="a" href="#works" style={{ display: 'block' }}>
      <SpringHover
        as="article"
        className="work-card"
        // Low tension, high friction: a heavy, unhurried lift that suits a
        // large surface. Small elements use the opposite.
        tension={260}
        friction={22}
        to={{ y: -8, scale: 1.012 }}
      >
        <div className="work-meta">
          <span>
            {work.category} — {work.year}
          </span>
          <SpringHover
            className="work-badge"
            tension={280}
            friction={18}
            to={{ rotate: 45, scale: 1.08 }}
          >
            <Icon name="arrow-up-right" />
          </SpringHover>
        </div>

        {/* Logo watermark behind the text. */}
        <div className="work-wm">
          <span className="work-wm-in">
            <Icon name="logo" />
            <sup>®</sup>
          </span>
        </div>

        <div className="work-bottom">
          <h3>{work.name}</h3>
          <p>{work.desc}</p>
          <div className="work-tags">
            {work.tags.map((tag) => (
              <Chip key={tag}>{tag}</Chip>
            ))}
          </div>
        </div>
      </SpringHover>
    </HoverGroup>
  );
}
