/**
 * Pill button / link — the site's primary call to action.
 *
 * Three nested layers, each with a job:
 *   .pill-root   the interactive element (button or anchor) and the hover group
 *   .pill-scale  the spring target that scales on hover
 *   .pill        the painted surface (background, border, padding)
 *
 * They are separate so scaling never fights the element's layout box, and so
 * the arrow badge can run its own spring inside the same hover group — hover
 * the button and the pill grows while the arrow slides.
 *
 * @param {'dark'|'light'|'outline'} [props.variant]
 * @param {false|'right'|'up-right'} [props.arrow] Trailing badge, if any.
 * @param {'button'|'a'}             [props.as]
 */

import HoverGroup from './HoverGroup.jsx';
import SpringHover from './SpringHover.jsx';
import Icon from '../icons/Icon.jsx';

/** Each arrow direction nudges the way it points. */
const ARROW_CONFIG = {
  right: { icon: 'arrow-right', to: { x: 3 } },
  'up-right': { icon: 'arrow-up-right', to: { x: 2, y: -2 } },
};

export default function Pill({
  as = 'button',
  variant = 'dark',
  arrow = false,
  className,
  children,
  ...rest
}) {
  const arrowConfig = arrow ? ARROW_CONFIG[arrow] : null;

  const pillClasses = ['pill', variant, arrowConfig && 'has-arrow']
    .filter(Boolean)
    .join(' ');

  return (
    <HoverGroup
      as={as}
      className={className ? `pill-root ${className}` : 'pill-root'}
      // Buttons default to type="submit" inside a form, which would submit the
      // contact form from any pill that happens to sit in one.
      type={as === 'button' && rest.type === undefined ? 'button' : rest.type}
      {...rest}
    >
      <SpringHover className="pill-scale" to={{ scale: 1.04 }}>
        <span className={pillClasses}>
          {children}

          {arrowConfig && (
            <span className="pill-badge">
              <SpringHover style={{ display: 'grid', placeItems: 'center' }} to={arrowConfig.to}>
                <Icon name={arrowConfig.icon} />
              </SpringHover>
            </span>
          )}
        </span>
      </SpringHover>
    </HoverGroup>
  );
}
