/**
 * Site header — brand mark, inline nav, clock, and the menu trigger.
 *
 * Absolutely positioned over the hero rather than fixed: it scrolls away with
 * the hero, and the overlay menu takes over from there.
 *
 * The inline nav only appears from 1024px; below that the menu button is the
 * sole navigation entry point.
 */

import Shell from '../common/Shell.jsx';
import HoverGroup from '../common/HoverGroup.jsx';
import SpringHover from '../common/SpringHover.jsx';
import Reveal from '../reveal/Reveal.jsx';
import Icon from '../icons/Icon.jsx';
import Clock from './Clock.jsx';
import { NAV_ITEMS } from '../../data/navItems.js';
import { useScroll } from '../../context/ScrollProvider.jsx';
import { useUI } from '../../context/UIProvider.jsx';
import { EASE_DEFAULT } from '../../config/easings.js';
import '../../styles/components/header.css';

export default function Header() {
  const { scrollToId } = useScroll();
  const { openMenu, openModal } = useUI();

  /** A nav item either opens the contact modal or scrolls to a section. */
  function handleNavClick(item) {
    if (item.modal) {
      openModal();
      return;
    }
    scrollToId(item.target);
  }

  return (
    <Reveal
      as="header"
      id="header"
      offsets={{ y: -14, o: 0 }}
      delay={150}
      duration={700}
      ease={EASE_DEFAULT}
      // Visible on first paint, so it must wait for the loader.
      gate
    >
      <Shell className="header-inner">
        <HoverGroup
          as="button"
          type="button"
          className="brand-btn"
          onClick={() => scrollToId('home')}
          aria-label="Lumora — back to top"
        >
          <SpringHover
            style={{ display: 'flex', alignItems: 'center', gap: '.5rem' }}
            to={{ scale: 1.04 }}
          >
            <Icon name="logo" />
            <span>Lumora</span>
          </SpringHover>
        </HoverGroup>

        <nav className="nav-primary" aria-label="Primary">
          <ul>
            {NAV_ITEMS.map((item) => (
              <li key={item.label}>
                <HoverGroup
                  as="button"
                  type="button"
                  onClick={() => handleNavClick(item)}
                  aria-current={item.current ? 'page' : undefined}
                >
                  {/* Links rest at 80% opacity and lift to full on hover. */}
                  <SpringHover
                    style={{ display: 'inline-flex', alignItems: 'center', gap: '.375rem' }}
                    tension={320}
                    friction={22}
                    from={{ y: 0, opacity: 0.8 }}
                    to={{ y: -2, opacity: 1 }}
                  >
                    {item.label}
                    {item.caret && (
                      <span className="nav-caret" aria-hidden="true">
                        ▾
                      </span>
                    )}
                  </SpringHover>
                </HoverGroup>
              </li>
            ))}
          </ul>
        </nav>

        <div className="header-right">
          <Clock />

          <HoverGroup
            as="button"
            type="button"
            className="menu-btn"
            onClick={openMenu}
            aria-label="Open menu"
          >
            <SpringHover tension={320} friction={18} to={{ scale: 1.05 }}>
              <Icon name="grid" />
              {/* Label is hidden below 640px; the icon carries it alone. */}
              <span className="menu-word">Menu</span>
            </SpringHover>
          </HoverGroup>
        </div>
      </Shell>
    </Reveal>
  );
}
