/**
 * Page loader.
 *
 * A dark panel over the whole viewport that sweeps a progress bar 0 -> 100 and
 * then slides up out of the way, revealing the hero underneath.
 *
 * The progress is choreography, not measurement — it runs for a fixed FILL_MS
 * regardless of what is actually loading. That is deliberate: it gives the hero
 * imagery a moment to decode and gives the entrance animations a clean stage,
 * rather than flashing an unstyled page and animating into a half-painted hero.
 *
 * On exit it calls `onExit`, which releases the gate that the hero's reveals
 * are waiting on (see IntroProvider).
 */

import { useEffect, useRef, useState } from 'react';
import Icon from '../icons/Icon.jsx';
import { useScrollLock } from '../../context/ScrollProvider.jsx';
import { FILL_MS, LOADER_EXIT_TIMEOUT_MS } from '../../config/constants.js';
import { easeInOutCubic } from '../../config/easings.js';
import '../../styles/components/loader.css';

export default function Loader({ onExit }) {
  const [progress, setProgress] = useState(0);
  const [exiting, setExiting] = useState(false);
  const [hidden, setHidden] = useState(false);

  const loaderRef = useRef(null);

  // Nothing should scroll behind the loader. Released automatically when this
  // component unmounts.
  useScrollLock(!hidden);

  // --- Progress sweep ---
  useEffect(() => {
    let frameId;
    const start = performance.now();

    function frame(now) {
      const t = Math.min((now - start) / FILL_MS, 1);
      setProgress(Math.round(easeInOutCubic(t) * 100));

      if (t < 1) {
        frameId = requestAnimationFrame(frame);
        return;
      }
      setExiting(true);
    }

    frameId = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(frameId);
  }, []);

  // --- Exit: slide away, then unmount ---
  useEffect(() => {
    if (!exiting) return undefined;

    const element = loaderRef.current;
    let finished = false;

    function finish() {
      if (finished) return;
      finished = true;

      // Release the gate first so the hero's reveals start while the panel is
      // still clearing — the two motions overlap instead of queueing.
      onExit?.();
      setHidden(true);
    }

    // Filtered by property and target: child elements transition too, and any
    // of those bubbling up would end the loader early.
    function onTransitionEnd(event) {
      if (event.propertyName === 'transform' && event.target === element) finish();
    }

    element?.addEventListener('transitionend', onTransitionEnd);

    // transitionend never fires in a backgrounded tab, and is suppressed
    // entirely under prefers-reduced-motion. Without this the page would stay
    // locked behind a black panel.
    const fallback = setTimeout(finish, LOADER_EXIT_TIMEOUT_MS);

    return () => {
      element?.removeEventListener('transitionend', onTransitionEnd);
      clearTimeout(fallback);
    };
  }, [exiting, onExit]);

  if (hidden) return null;

  return (
    <div id="loader" ref={loaderRef} className={exiting ? 'exit' : undefined}>
      <div id="loader-content">
        <div className="loader-brand">
          <Icon name="logo" />
          <span>Lumora</span>
        </div>
        <p className="loader-tag">Bold ideas, shipped with quiet precision.</p>
      </div>

      <div id="loader-progress">
        <div className="loader-track">
          <div className="loader-fill" style={{ width: `${progress}%` }} />
        </div>
        <div className="loader-meta">
          <span>Loading</span>
          {/* Zero-padded to three digits so the label never changes width. */}
          <span className="loader-count tnum">{String(progress).padStart(3, '0')}</span>
        </div>
      </div>
    </div>
  );
}
