/**
 * Services section — a hairline-separated list of offerings.
 */

import Shell from '../common/Shell.jsx';
import Eyebrow from '../common/Eyebrow.jsx';
import Reveal from '../reveal/Reveal.jsx';
import RevealLines from '../reveal/RevealLines.jsx';
import ServiceRow from './ServiceRow.jsx';
import { SERVICES } from '../../data/services.js';
import '../../styles/components/services.css';

export default function Services() {
  return (
    <section id="services">
      <Shell className="services-inner">
        <Reveal offsets={{ y: 10, o: 0 }} duration={700}>
          <Eyebrow>Services</Eyebrow>
        </Reveal>

        <RevealLines className="services-h2" delay={120} lines={['What we do best']} />

        <ul>
          {SERVICES.map((service, index) => (
            <li className="svc-li" key={service.idx}>
              <Reveal
                offsets={{ y: 24, o: 0 }}
                delay={index * 80}
                duration={800}
                ease="cubic-bezier(.16,1,.3,1)"
              >
                <ServiceRow service={service} />
              </Reveal>
            </li>
          ))}
        </ul>
      </Shell>
    </section>
  );
}
