/**
 * Contact form validation rules.
 *
 * Front-end only, so this is the sole check. If you later add a backend,
 * mirror these rules there and treat the server as the authority — anything
 * enforced only in the browser can be bypassed.
 */

export const LIMITS = {
  name: { min: 2, max: 100 },
  email: { max: 200 },
  project: { min: 10, max: 2000 },
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * @param {{ name: string, email: string, project: string }} values
 * @returns {Record<string, string>} Field name -> message. Empty when valid.
 */
export function validateForm(values) {
  const errors = {};

  const name = values.name.trim();
  const email = values.email.trim();
  const project = values.project.trim();

  if (!name) errors.name = 'Name is required.';
  else if (name.length < LIMITS.name.min)
    errors.name = `Name must be at least ${LIMITS.name.min} characters.`;
  else if (name.length > LIMITS.name.max)
    errors.name = `Name must be under ${LIMITS.name.max} characters.`;

  if (!email) errors.email = 'Email is required.';
  else if (!EMAIL_PATTERN.test(email)) errors.email = 'Enter a valid email address.';

  if (!project) errors.project = 'Tell us a little about your project.';
  else if (project.length < LIMITS.project.min)
    errors.project = `Please use at least ${LIMITS.project.min} characters.`;
  else if (project.length > LIMITS.project.max)
    errors.project = `Please keep this under ${LIMITS.project.max} characters.`;

  return errors;
}
