/**
 * "Trusted by" client grid in the hero.
 */

import HoverGroup from '../common/HoverGroup.jsx';
import SpringHover from '../common/SpringHover.jsx';
import Reveal from '../reveal/Reveal.jsx';
import Icon from '../icons/Icon.jsx';
import { PARTNERS } from '../../data/partners.js';

export default function Partners() {
  return (
    <Reveal
      className="partners"
      offsets={{ y: 14, o: 0 }}
      delay={550}
      duration={800}
      ease="cubic-bezier(.16,1,.3,1)"
      gate
    >
      <p className="partners-label">Trusted by</p>
      <ul className="partners-grid">
        {PARTNERS.map((partner) => (
          <HoverGroup as="li" key={partner}>
            {/* Names rest dimmed and lift to full opacity on hover. */}
            <SpringHover
              className="partner"
              tension={320}
              friction={20}
              from={{ y: 0, opacity: 0.7 }}
              to={{ y: -2, opacity: 1 }}
            >
              <Icon name="circle-dot" />
              <span>{partner}</span>
            </SpringHover>
          </HoverGroup>
        ))}
      </ul>
    </Reveal>
  );
}
