/**
 * Entry point.
 *
 * Global styles are imported here, in cascade order: tokens define the custom
 * properties everything else reads, base resets and sets the adaptive grid,
 * primitives supply the shared building blocks. Per-section stylesheets are
 * imported by the components that own them.
 */

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

import './styles/tokens.css';
import './styles/base.css';
import './styles/primitives.css';

import App from './App.jsx';

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
