/**
 * Centred, width-capped content column (max-width: var(--container-shell)).
 *
 * Used by every section, so the horizontal rhythm is defined in exactly one
 * place.
 */

export default function Shell({ as: Tag = 'div', className, children, ...rest }) {
  return (
    <Tag className={className ? `shell ${className}` : 'shell'} {...rest}>
      {children}
    </Tag>
  );
}
