/**
 * "We Build → Better" band between About and the portfolio.
 *
 * Purely typographic — four pill tiles that stagger in as the band scrolls
 * into view.
 */

import Shell from '../common/Shell.jsx';
import HoverGroup from '../common/HoverGroup.jsx';
import SpringHover from '../common/SpringHover.jsx';
import Reveal from '../reveal/Reveal.jsx';
import Icon from '../icons/Icon.jsx';
import { CREATE_ITEMS } from '../../data/createItems.js';
import '../../styles/components/create-band.css';

export default function CreateBand() {
  return (
    <section className="create-band" aria-label="We build better">
      <Shell as="ul" className="create-list">
        {CREATE_ITEMS.map((item, index) => (
          <li key={item.word || 'arrow'}>
            <Reveal
              offsets={{ y: 28, o: 0 }}
              // Tiles arrive left to right, so the phrase reads as it lands.
              delay={index * 120}
              duration={800}
              ease="cubic-bezier(.16,1,.3,1)"
            >
              <HoverGroup>
                <SpringHover
                  className={`create-tile ${item.variant}`}
                  tension={300}
                  friction={18}
                  to={{ scale: 1.03 }}
                >
                  {item.arrow ? <Icon name="arrow-right" /> : item.word}
                </SpringHover>
              </HoverGroup>
            </Reveal>
          </li>
        ))}
      </Shell>
    </section>
  );
}
