/**
 * Shared easing curves and durations.
 *
 * The reveal system writes CSS transitions from JS, so these live as strings
 * rather than CSS custom properties.
 */

/** Line reveals — a firm, decisive settle. */
export const EASE_LINE = 'cubic-bezier(.215,.61,.355,1)';

/** Word reveals — softer, since many run in quick succession. */
export const EASE_WORD = 'cubic-bezier(.165,.84,.44,1)';

/** Everything else. */
export const EASE_DEFAULT = 'cubic-bezier(.22,1,.36,1)';

/** Hero carousel cross-fade. */
export const EASE_CAROUSEL = 'cubic-bezier(.2,.8,.2,1)';

export const DURATION = {
  line: 900,
  word: 700,
  block: 800,
  carousel: 400,
};

/**
 * Slow start, slow finish. Used for the loader sweep so it doesn't look like a
 * linear fake — real loads stall in the middle.
 */
export function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}
