/**
 * Scroll-position-driven counter.
 *
 * The displayed number is a function of where the element sits in the viewport,
 * not of elapsed time — so scrolling back up counts down, and the number tracks
 * the scrollbar rather than playing a fixed animation. That is what makes the
 * stats panel feel attached to the page.
 *
 * Returns the current value; attach the returned ref to the number element.
 */

import { useCallback, useEffect, useRef, useState } from 'react';

/** Coalesces scroll bursts into one measurement every ~30ms. */
const THROTTLE_MS = 30;

/**
 * @param {number} target Final value to count up to
 * @returns {[import('react').RefObject<HTMLElement>, number]}
 */
export function useCountUp(target) {
  const ref = useRef(null);
  const [value, setValue] = useState(0);

  const measure = useCallback(() => {
    const element = ref.current;
    if (!element) return;

    const viewportHeight = window.innerHeight;
    const rect = element.getBoundingClientRect();

    // Progress runs 0 -> 1 as the element travels from the bottom edge of the
    // viewport up to the middle. Including half the element's own height stops
    // tall elements from reaching 100% before they are fully visible.
    const span = viewportHeight / 2 + rect.height / 2;
    const progress = Math.max(0, Math.min(1, (viewportHeight - rect.top) / span));

    setValue(Math.round(progress * target));
  }, [target]);

  useEffect(() => {
    let throttled = false;

    function onScroll() {
      if (throttled) return;
      throttled = true;
      setTimeout(() => {
        throttled = false;
        measure();
      }, THROTTLE_MS);
    }

    // Measure once on mount: the panel may already be in view on a short page
    // or after a reload part-way down.
    measure();

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);

    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
    };
  }, [measure]);

  return [ref, value];
}
