/**
 * Gates the hero entrance animations behind the page loader.
 *
 * Hero elements are visible in the viewport from the very first frame, so their
 * IntersectionObserver fires immediately — while the loader is still covering
 * the screen. Without a gate the entire entrance choreography would play unseen
 * and the hero would simply be *there* when the loader lifts.
 *
 * Gated reveals therefore wait for `introReady`, which the loader flips as it
 * exits. Replaces the original's `introReady` flag + `gateQueue` array.
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import { INTRO_SAFETY_MS } from '../config/constants.js';

const IntroContext = createContext(null);

export function IntroProvider({ children }) {
  const [introReady, setIntroReady] = useState(false);

  const markIntroReady = useCallback(() => setIntroReady(true), []);

  // Safety net: if the loader's transition never completes — a background tab
  // throttles rAF, an image hangs — the page must not stay blank and locked.
  useEffect(() => {
    if (introReady) return undefined;

    const timer = setTimeout(() => setIntroReady(true), INTRO_SAFETY_MS);
    return () => clearTimeout(timer);
  }, [introReady]);

  const value = useMemo(
    () => ({ introReady, markIntroReady }),
    [introReady, markIntroReady],
  );

  return <IntroContext.Provider value={value}>{children}</IntroContext.Provider>;
}

export function useIntro() {
  const context = useContext(IntroContext);
  if (!context) throw new Error('useIntro must be used within <IntroProvider>');
  return context;
}
