/**
 * Smooth scrolling and page scroll locking.
 *
 * Owns the single Lenis instance and its rAF loop, and exposes:
 *   scrollToId(id) — smooth-scroll to a section
 *   lockScroll()   — freeze the page (overlays)
 *   unlockScroll() — release it
 *
 * ── Why a lock counter ──────────────────────────────────────────────────────
 * Two overlays can lock scrolling: the nav menu and the contact modal, and the
 * menu hands off directly to the modal. The original coordinated this by having
 * each closer peek at the other's DOM state before restoring scroll, which
 * couples them and breaks the moment a third overlay appears.
 *
 * Here every lock increments a counter and every unlock decrements it; scroll
 * resumes only at zero. Callers never need to know about each other.
 * ───────────────────────────────────────────────────────────────────────────
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
} from 'react';
import Lenis from 'lenis';

const ScrollContext = createContext(null);

export function ScrollProvider({ children }) {
  const lenisRef = useRef(null);
  const lockCountRef = useRef(0);

  useEffect(() => {
    // Browsers restore the previous scroll position on reload, which would drop
    // the visitor mid-page behind the loader.
    window.history.scrollRestoration = 'manual';
    window.scrollTo(0, 0);

    const lenis = new Lenis({ smoothWheel: true });
    lenisRef.current = lenis;

    let frameId;
    function raf(time) {
      lenis.raf(time);
      frameId = requestAnimationFrame(raf);
    }
    frameId = requestAnimationFrame(raf);

    return () => {
      cancelAnimationFrame(frameId);
      lenis.destroy();
      lenisRef.current = null;
    };
  }, []);

  /**
   * Freezing <html> as well as stopping Lenis is deliberate: Lenis only ignores
   * wheel/touch input, it does not stop the keyboard (space, page-down) or a
   * focused element scrolling itself into view.
   */
  const freezeDocument = useCallback((frozen) => {
    const html = document.documentElement;

    if (frozen) {
      html.style.position = 'relative';
      html.style.overflow = 'hidden';
      html.style.height = '100%';
    } else {
      html.style.removeProperty('position');
      html.style.removeProperty('overflow');
      html.style.removeProperty('height');
    }
  }, []);

  const lockScroll = useCallback(() => {
    lockCountRef.current += 1;
    // Only act on the transition from 0 -> 1; nested locks are no-ops.
    if (lockCountRef.current === 1) {
      lenisRef.current?.stop();
      freezeDocument(true);
    }
  }, [freezeDocument]);

  const unlockScroll = useCallback(() => {
    // Guard against an unbalanced unlock driving the counter negative, which
    // would leave the page permanently frozen on the next lock.
    lockCountRef.current = Math.max(0, lockCountRef.current - 1);
    if (lockCountRef.current === 0) {
      freezeDocument(false);
      lenisRef.current?.start();
    }
  }, [freezeDocument]);

  /** Smooth-scrolls to a section by element id. Unknown ids are ignored. */
  const scrollToId = useCallback((id) => {
    const element = document.getElementById(id);
    if (!element) return;

    // Lenis drives the animation itself, keeping this consistent with wheel
    // scrolling. (The original stopped Lenis and used native smooth scroll,
    // which briefly handed control back to the browser mid-transition.)
    if (lenisRef.current) {
      lenisRef.current.scrollTo(element, { offset: 0, duration: 1.2 });
      return;
    }

    element.scrollIntoView({ behavior: 'smooth' });
  }, []);

  const value = useMemo(
    () => ({ scrollToId, lockScroll, unlockScroll }),
    [scrollToId, lockScroll, unlockScroll],
  );

  return <ScrollContext.Provider value={value}>{children}</ScrollContext.Provider>;
}

export function useScroll() {
  const context = useContext(ScrollContext);
  if (!context) throw new Error('useScroll must be used within <ScrollProvider>');
  return context;
}

/**
 * Locks page scroll for as long as `active` is true, releasing it on unmount.
 * Saves every overlay from hand-pairing lock/unlock calls.
 */
export function useScrollLock(active) {
  const { lockScroll, unlockScroll } = useScroll();

  useEffect(() => {
    if (!active) return undefined;

    lockScroll();
    return unlockScroll;
  }, [active, lockScroll, unlockScroll]);
}
