/**
 * Contact request form.
 *
 * Moves through idle -> sending -> success.
 *
 * This is a front-end-only project: there is no backend and nothing leaves the
 * browser. Submitting validates the input, pauses briefly so the "Sending…"
 * state is visible, then shows the confirmation panel.
 *
 * To wire this up for real, replace the `simulateSubmit` call in `handleSubmit`
 * with a `fetch` to your endpoint and surface failures through `setFormError` —
 * the error UI below is already built for it.
 */

import { useEffect, useRef, useState } from 'react';
import Pill from '../../components/common/Pill.jsx';
import { validateForm } from './validateForm.js';

const EMPTY_VALUES = { name: '', email: '', project: '' };

/** How long the "Sending…" state shows before the confirmation. */
const SUBMIT_DELAY_MS = 700;

export default function RequestForm({ onSuccess }) {
  const [values, setValues] = useState(EMPTY_VALUES);
  const [fieldErrors, setFieldErrors] = useState({});
  const [formError, setFormError] = useState(null);
  const [status, setStatus] = useState('idle');

  const sending = status === 'sending';

  // Tracked so the pending timeout can be cancelled if the modal closes
  // mid-submit — otherwise it would fire against an unmounted component.
  const timerRef = useRef(null);
  useEffect(() => () => clearTimeout(timerRef.current), []);

  function handleChange(event) {
    const { name, value } = event.target;
    setValues((current) => ({ ...current, [name]: value }));

    // Clear this field's error as soon as it's edited. Leaving it until the
    // next submit makes the form feel like it's arguing with the visitor.
    setFieldErrors((current) => {
      if (!current[name]) return current;
      const { [name]: _removed, ...rest } = current;
      return rest;
    });
  }

  function handleSubmit(event) {
    event.preventDefault();
    if (sending) return;

    setFormError(null);

    const errors = validateForm(values);
    if (Object.keys(errors).length > 0) {
      setFieldErrors(errors);
      return;
    }

    setStatus('sending');

    timerRef.current = setTimeout(() => {
      setStatus('success');
      setValues(EMPTY_VALUES);
      onSuccess?.();
    }, SUBMIT_DELAY_MS);
  }

  /** Shared props for the three inputs. */
  const fieldProps = (name) => ({
    name,
    value: values[name],
    onChange: handleChange,
    disabled: sending,
    className: fieldErrors[name] ? 'invalid' : undefined,
    'aria-invalid': fieldErrors[name] ? 'true' : undefined,
    'aria-describedby': fieldErrors[name] ? `${name}-error` : undefined,
  });

  /** Inline message under a field. */
  const fieldError = (name) =>
    fieldErrors[name] && (
      <span className="field-error" id={`${name}-error`}>
        {fieldErrors[name]}
      </span>
    );

  return (
    // noValidate: the browser's own bubbles would clash with the styled
    // messages below each field.
    <form onSubmit={handleSubmit} noValidate>
      <label>
        <span className="field-cap">Name</span>
        <input type="text" placeholder="Your name" autoComplete="name" {...fieldProps('name')} />
        {fieldError('name')}
      </label>

      <label>
        <span className="field-cap">Email</span>
        <input
          type="email"
          placeholder="you@company.com"
          autoComplete="email"
          {...fieldProps('email')}
        />
        {fieldError('email')}
      </label>

      <label>
        <span className="field-cap">Project</span>
        <textarea
          rows={4}
          placeholder="A few words about your project, timeline, and budget."
          {...fieldProps('project')}
        />
        {fieldError('project')}
      </label>

      {/* Unused while submission is simulated — kept wired up so adding a real
          endpoint needs no extra markup. */}
      {formError && (
        <p className="form-error" role="alert">
          {formError}
        </p>
      )}

      <div className="modal-bottom">
        <p className="modal-note">We reply within one business day.</p>
        <Pill type="submit" variant="dark" arrow="up-right" disabled={sending}>
          {sending ? 'Sending…' : 'Send request'}
        </Pill>
      </div>
    </form>
  );
}
