/**
 * Portfolio section — a two-column grid of case study cards.
 */

import Shell from '../common/Shell.jsx';
import Eyebrow from '../common/Eyebrow.jsx';
import Reveal from '../reveal/Reveal.jsx';
import RevealLines from '../reveal/RevealLines.jsx';
import WorkCard from './WorkCard.jsx';
import { WORKS } from '../../data/works.js';
import '../../styles/components/works.css';

export default function Works() {
  return (
    <section id="works">
      <Shell className="works-inner">
        <div className="works-head">
          <Reveal offsets={{ y: 10, o: 0 }} duration={700}>
            <Eyebrow boxed>Portfolio</Eyebrow>
          </Reveal>
          <RevealLines className="works-h2" delay={120} lines={['Selected Work']} />
        </div>

        <ul className="works-grid">
          {WORKS.map((work, index) => (
            <li key={work.name}>
              <Reveal
                offsets={{ y: 48, o: 0 }}
                // Cascades the cards rather than dropping all four at once.
                delay={index * 90}
                duration={900}
                ease="cubic-bezier(.16,1,.3,1)"
              >
                <WorkCard work={work} />
              </Reveal>
            </li>
          ))}
        </ul>
      </Shell>
    </section>
  );
}
