/**
 * Hero capability card — a small carousel that cross-fades between three lines.
 *
 * ── Why two items render at once ────────────────────────────────────────────
 * The outgoing item slides one way while the incoming slides in from the other,
 * so both must exist in the DOM during the transition. `prev` holds the
 * outgoing index until the animation ends, then is cleared.
 *
 * Each item is keyed by its index, so React mounts a genuinely new node for the
 * incoming one — that is what lets it start at its offset position without
 * transitioning into it. The outgoing node keeps its identity, so changing its
 * style animates.
 *
 * (The original did this by hand with createElement/appendChild/removeChild.)
 * ───────────────────────────────────────────────────────────────────────────
 */

import { useCallback, useEffect, useState } from 'react';
import Icon from '../icons/Icon.jsx';
import Reveal from '../reveal/Reveal.jsx';
import { HERO_ITEMS } from '../../data/heroItems.js';
import { DURATION, EASE_CAROUSEL } from '../../config/easings.js';

/** Vertical travel of the cross-fade, in px. */
const SLIDE_DISTANCE = 14;

/** Slightly longer than the transition, so removal never clips it. */
const CLEANUP_MS = DURATION.carousel + 20;

const TRANSITION =
  `transform ${DURATION.carousel}ms ${EASE_CAROUSEL}, ` +
  `opacity ${DURATION.carousel}ms ${EASE_CAROUSEL}`;

export default function HeroCard() {
  const total = HERO_ITEMS.length;

  const [{ index, prev, direction }, setCarousel] = useState({
    index: 0,
    prev: null,
    direction: 1,
  });

  // False for one frame after a change, so the incoming item can be painted at
  // its start position before it animates.
  const [entered, setEntered] = useState(true);

  const go = useCallback(
    (step) => {
      setCarousel((current) => {
        const next = (current.index + step + total) % total;
        if (next === current.index) return current;

        return { index: next, prev: current.index, direction: step > 0 ? 1 : -1 };
      });
      setEntered(false);
    },
    [total],
  );

  // Flip to the settled position on the next frame. Two frames deep: the first
  // commits the mount, the second starts the transition against it.
  useEffect(() => {
    if (entered) return undefined;

    let inner;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setEntered(true));
    });

    return () => {
      cancelAnimationFrame(outer);
      if (inner) cancelAnimationFrame(inner);
    };
  }, [entered]);

  // Drop the outgoing item once its animation has finished.
  useEffect(() => {
    if (prev === null) return undefined;

    const timer = setTimeout(
      () => setCarousel((current) => ({ ...current, prev: null })),
      CLEANUP_MS,
    );
    return () => clearTimeout(timer);
  }, [prev, index]);

  /** @param {'in'|'out'} role */
  function renderItem(itemIndex, role) {
    const item = HERO_ITEMS[itemIndex];

    // Incoming enters from the direction of travel; outgoing leaves the
    // opposite way, so the pair reads as one continuous movement.
    const offset =
      role === 'in'
        ? `translateY(${direction * SLIDE_DISTANCE}px)`
        : `translateY(${-direction * SLIDE_DISTANCE}px)`;

    const settled = role === 'in' ? entered : false;

    return (
      <div
        className="hero-item"
        key={itemIndex}
        style={{
          transform: settled ? 'translateY(0)' : offset,
          opacity: settled ? 1 : 0,
          transition: TRANSITION,
        }}
      >
        <span className="cap">{item.caption}</span>
        <span className="ttl">{item.title}</span>
      </div>
    );
  }

  /** Advance on Enter/Space, matching the row's role="button". */
  function onKeyDown(event) {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      go(1);
    }
  }

  return (
    <Reveal
      className="hero-card"
      offsets={{ y: 16, o: 0, scale: 0.96 }}
      delay={400}
      duration={800}
      ease="cubic-bezier(.16,1,.3,1)"
      gate
    >
      <div
        className="hero-card-row"
        role="button"
        tabIndex={0}
        onClick={() => go(1)}
        onKeyDown={onKeyDown}
        aria-label="Next capability"
      >
        <div className="hero-tile">
          <Icon name="logo" />
        </div>

        <div className="hero-panel">
          <div className="hero-slot">
            {prev !== null && renderItem(prev, 'out')}
            {renderItem(index, 'in')}
          </div>

          <div className="hero-card-bottom">
            <div className="hero-dots">
              {HERO_ITEMS.map((item, dotIndex) => (
                <span
                  key={item.caption}
                  className={dotIndex === index ? 'hero-dot on' : 'hero-dot'}
                />
              ))}
            </div>

            <div className="hero-navs">
              {/* stopPropagation keeps the arrows from also firing the row's
                  own "advance" handler. */}
              <button
                type="button"
                className="hero-nav prev"
                aria-label="Previous"
                onClick={(event) => {
                  event.stopPropagation();
                  go(-1);
                }}
              >
                <Icon name="arrow-right" />
              </button>
              <button
                type="button"
                className="hero-nav next"
                aria-label="Next"
                onClick={(event) => {
                  event.stopPropagation();
                  go(1);
                }}
              >
                <Icon name="arrow-right" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </Reveal>
  );
}
