/**
 * Hero background: the base image plus the canvas the cursor paints on.
 *
 * All the drawing logic lives in useLiquidReveal; this component only owns the
 * markup and the two refs the hook needs.
 */

import { useRef } from 'react';
import { useLiquidReveal } from '../../hooks/useLiquidReveal.js';
import { HERO_IMAGES } from '../../config/constants.js';

export default function LiquidCanvas() {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);

  useLiquidReveal(containerRef, canvasRef, HERO_IMAGES.brush);

  return (
    <div className="liquid" ref={containerRef}>
      <img
        src={HERO_IMAGES.base}
        alt="Lumora studio work"
        // This is the largest element in the viewport on load — the LCP
        // candidate — so it jumps the queue ahead of other requests.
        // Lowercase: React 18 does not recognise the camelCase form and warns.
        fetchpriority="high"
        decoding="async"
      />
      {/* Purely decorative: the effect conveys no information. */}
      <canvas ref={canvasRef} aria-hidden="true" />
    </div>
  );
}
