/**
 * Stats section — a dark inset panel of headline numbers.
 */

import Shell from '../common/Shell.jsx';
import Eyebrow from '../common/Eyebrow.jsx';
import Reveal from '../reveal/Reveal.jsx';
import RevealLines from '../reveal/RevealLines.jsx';
import StatItem from './StatItem.jsx';
import { STATS } from '../../data/stats.js';
import '../../styles/components/stats.css';

export default function Stats() {
  return (
    <section className="stats" aria-label="By the numbers">
      <Shell className="stats-inner">
        <Reveal
          className="stats-panel"
          // A long travel with a barely perceptible scale: the whole panel
          // rises into place as one object.
          offsets={{ y: 40, o: 0, scale: 0.99 }}
          duration={900}
          ease="cubic-bezier(.16,1,.3,1)"
        >
          <Eyebrow light>By the numbers</Eyebrow>

          <RevealLines
            className="stats-h2"
            delay={120}
            lines={['Proof in the work,', 'not the words.']}
          />

          <ul className="stats-grid">
            {STATS.map((stat, index) => (
              <StatItem stat={stat} index={index} key={stat.label} />
            ))}
          </ul>
        </Reveal>
      </Shell>
    </section>
  );
}
