/**
 * A single stat, with its number driven by scroll position.
 *
 * Each stat owns its own useCountUp rather than sharing one, so the number
 * responds to where *it* sits in the viewport.
 */

import Reveal from '../reveal/Reveal.jsx';
import { useCountUp } from '../../hooks/useCountUp.js';

export default function StatItem({ stat, index }) {
  const [ref, value] = useCountUp(stat.value);

  return (
    <Reveal
      as="li"
      offsets={{ y: 20, o: 0 }}
      delay={index * 90}
      duration={800}
      ease="cubic-bezier(.16,1,.3,1)"
    >
      <p className="stat-num">
        {/* Only the digits animate; the suffix (+, %) stays put. */}
        <span ref={ref}>{value}</span>
        {stat.suffix}
      </p>
      <p className="stat-label">{stat.label}</p>
    </Reveal>
  );
}
