/**
 * Headline reveal — each line slides up from behind a hard mask.
 *
 * Lines are authored explicitly rather than measured, because the break points
 * are a typographic decision, not whatever the browser happens to wrap at:
 *
 *   <RevealLines as="h1" className="hero-h1"
 *     lines={['Bold ideas,', 'shipped with', 'quiet precision']} />
 *
 * Each line is a clipping `.line` wrapper around a `.line-i` that translates
 * from 100% (fully below the mask) to 0.
 *
 * @param {string[]} props.lines
 * @param {number}  [props.stagger] ms between consecutive lines.
 */

import { useReveal } from '../../hooks/useReveal.js';
import { DURATION, EASE_LINE } from '../../config/easings.js';

export default function RevealLines({
  as: Tag = 'h2',
  lines = [],
  delay = 0,
  stagger = 120,
  duration = DURATION.line,
  gate = false,
  className,
  ...rest
}) {
  const [ref, played] = useReveal({ gate });

  return (
    <Tag ref={ref} className={className} {...rest}>
      {lines.map((line, index) => {
        const lineDelay = delay + index * stagger;

        return (
          // Lines are fixed content, so the index is a stable key.
          <span className="line" key={index}>
            <span
              className="line-i"
              style={{
                transform: played ? 'translateY(0%)' : 'translateY(100%)',
                opacity: played ? 1 : 0,
                transition:
                  `transform ${duration}ms ${EASE_LINE} ${lineDelay}ms, ` +
                  `opacity ${duration}ms ${EASE_LINE} ${lineDelay}ms`,
              }}
            >
              {line}
            </span>
          </span>
        );
      })}
    </Tag>
  );
}
