/**
 * Live local time, ticking once a second.
 *
 * Returns `{ time, date }` as pre-formatted strings, e.g. "9:41am" and
 * "12 March, 2025". Reads the visitor's clock — the studio is remote-first, so
 * "local time" means theirs.
 *
 * The original wrote into three separate DOM nodes via querySelectorAll on
 * every tick; here one state value feeds every consumer.
 */

import { useEffect, useState } from 'react';

const MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

function format(date) {
  // 12-hour clock: hour 0 must display as 12, not 0.
  const hours = date.getHours() % 12 || 12;
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const meridiem = date.getHours() >= 12 ? 'pm' : 'am';

  return {
    time: `${hours}:${minutes}${meridiem}`,
    date: `${date.getDate()} ${MONTHS[date.getMonth()]}, ${date.getFullYear()}`,
  };
}

export function useClock() {
  // Initialise from the real clock so the first paint is never a placeholder.
  const [value, setValue] = useState(() => format(new Date()));

  useEffect(() => {
    // Ticking every second rather than every minute keeps the display from
    // lagging up to 59s behind after a tab wakes from background throttling.
    const interval = setInterval(() => setValue(format(new Date())), 1000);
    return () => clearInterval(interval);
  }, []);

  return value;
}
