/**
 * Block-level entrance animation.
 *
 * Slides and/or fades its children in when they scroll into view. For text that
 * should animate line by line or word by word, use RevealLines / RevealWords.
 *
 *   <Reveal offsets={{ y: 20, o: 0 }} delay={200} gate>…</Reveal>
 *
 * @param {object}   props
 * @param {string}  [props.as]           Element to render. Default 'div'.
 * @param {object}  [props.offsets]      Starting offsets: x, y (px), scale, o (opacity).
 * @param {number}  [props.delay]        ms before the transition starts.
 * @param {number}  [props.duration]     ms.
 * @param {string}  [props.ease]         CSS timing function.
 * @param {number}  [props.finalOpacity] Resting opacity. Default 1.
 * @param {boolean} [props.gate]         Wait for the loader to finish.
 */

import { buildRevealStyle, useReveal } from '../../hooks/useReveal.js';
import { DURATION, EASE_DEFAULT } from '../../config/easings.js';

export default function Reveal({
  as: Tag = 'div',
  offsets = { y: 10, o: 0 },
  delay = 0,
  duration = DURATION.block,
  ease = EASE_DEFAULT,
  finalOpacity = 1,
  gate = false,
  style,
  children,
  ...rest
}) {
  const [ref, played] = useReveal({ gate });

  return (
    <Tag
      ref={ref}
      // Caller styles come last so a component can still override layout.
      style={{ ...buildRevealStyle(played, offsets, { delay, duration, ease }, finalOpacity), ...style }}
      {...rest}
    >
      {children}
    </Tag>
  );
}
