/**
 * Icon renderer.
 *
 * Replaces the original `paintIcons()`, which walked the DOM after every
 * innerHTML write and injected SVG strings by hand. Here the icon is just part
 * of the tree React already renders.
 *
 * The `<i data-icon>` wrapper is kept so the existing CSS sizing rules apply
 * unchanged.
 *
 * @param {object}  props
 * @param {string}  props.name      Key from the ICONS registry
 * @param {string} [props.className]
 * @param {string} [props.title]    Supply for a meaningful icon; omit to hide
 *                                  it from assistive tech (the common case,
 *                                  since icons here sit beside real text).
 */

import { ICONS } from './iconPaths.jsx';

export default function Icon({ name, className, title, ...rest }) {
  const icon = ICONS[name];

  // Fail loudly in development, render nothing in production, rather than
  // crashing the page over a typo in an icon name.
  if (!icon) {
    if (import.meta.env.DEV) console.warn(`<Icon />: unknown icon "${name}"`);
    return null;
  }

  return (
    <i data-icon={name} className={className} {...rest}>
      <svg
        viewBox={icon.viewBox}
        role={title ? 'img' : undefined}
        aria-hidden={title ? undefined : 'true'}
        {...icon.attrs}
      >
        {title && <title>{title}</title>}
        {icon.content}
      </svg>
    </i>
  );
}
