/**
 * A single service row.
 *
 * The hover effect is unusual: as well as fading a background in (`bg`), the
 * spring animates the row's horizontal padding (`pl` 1.5 -> 2rem, `pr` 1.5 ->
 * 1.25rem). The content shifts right as the surface appears, so the row feels
 * like it's leaning toward the cursor. CSS transitions could do this, but then
 * the padding and background could drift out of sync — one spring guarantees
 * they don't.
 */

import HoverGroup from '../common/HoverGroup.jsx';
import SpringHover from '../common/SpringHover.jsx';
import Icon from '../icons/Icon.jsx';

export default function ServiceRow({ service }) {
  return (
    <HoverGroup as="a" href="#services" style={{ display: 'block' }}>
      <SpringHover
        as="div"
        className="svc-row"
        // High friction relative to tension: a slow, weighty slide with no
        // bounce, which suits a wide horizontal element.
        tension={240}
        friction={26}
        from={{ bg: 0, pl: 1.5, pr: 1.5 }}
        to={{ bg: 1, pl: 2, pr: 1.25 }}
      >
        <span className="svc-idx">{service.idx}</span>
        <h3 className="svc-title">{service.title}</h3>
        {/* Hidden below 1024px — see .svc-desc. */}
        <p className="svc-desc">{service.desc}</p>
        <SpringHover className="svc-badge" tension={300} friction={18} to={{ x: 5 }}>
          <Icon name="arrow-up-right" />
        </SpringHover>
      </SpringHover>
    </HoverGroup>
  );
}
