/**
 * Full-screen navigation overlay.
 *
 * ── Two-stage visibility ────────────────────────────────────────────────────
 * `display` and `opacity` are tracked separately because neither works alone.
 * Toggling only opacity leaves an invisible full-screen layer swallowing every
 * click and keeping its links in the tab order. Toggling only display skips the
 * transition, since a transition cannot start on an element that was
 * display:none the frame before.
 *
 * So: mount with display:flex, wait for the browser to paint that, then add
 * `.open` to trigger the fade. On close, reverse it — fade out, then unmount
 * once the transition has finished.
 * ───────────────────────────────────────────────────────────────────────────
 */

import { useEffect, useRef, useState } from 'react';
import Shell from '../common/Shell.jsx';
import Icon from '../icons/Icon.jsx';
import { NAV_ITEMS } from '../../data/navItems.js';
import { useUI } from '../../context/UIProvider.jsx';
import { useScroll, useScrollLock } from '../../context/ScrollProvider.jsx';
import { useEscapeKey } from '../../hooks/useEscapeKey.js';
import { useClock } from '../../hooks/useClock.js';
import '../../styles/components/nav-menu.css';

/** Must match the opacity transition in nav-menu.css (0.45s + a little slack). */
const FADE_OUT_MS = 460;

export default function NavMenu() {
  const { menuOpen, closeMenu, closeMenuThen, openModal } = useUI();
  const { scrollToId } = useScroll();
  const { time } = useClock();

  const [mounted, setMounted] = useState(false); // drives `display`
  const [open, setOpen] = useState(false); // drives `opacity`
  const framesRef = useRef([]);

  useScrollLock(menuOpen);
  useEscapeKey(menuOpen, closeMenu);

  useEffect(() => {
    // Cancel any in-flight frame from a rapid open/close/open.
    framesRef.current.forEach(cancelAnimationFrame);
    framesRef.current = [];

    if (menuOpen) {
      setMounted(true);

      // Two frames: the first commits display:flex, the second starts the fade
      // against a style the browser has actually laid out.
      const outer = requestAnimationFrame(() => {
        const inner = requestAnimationFrame(() => setOpen(true));
        framesRef.current.push(inner);
      });
      framesRef.current.push(outer);

      return () => {
        framesRef.current.forEach(cancelAnimationFrame);
        framesRef.current = [];
      };
    }

    setOpen(false);
    const timer = setTimeout(() => setMounted(false), FADE_OUT_MS);
    return () => clearTimeout(timer);
  }, [menuOpen]);

  /** Closes the overlay first, then performs the item's action. */
  function handleNavClick(item) {
    closeMenuThen(() => {
      if (item.modal) openModal();
      else scrollToId(item.target);
    });
  }

  return (
    <div
      id="navmenu"
      className={open ? 'open' : undefined}
      style={{ display: mounted ? 'flex' : 'none' }}
      // Keeps the closed overlay out of the accessibility tree entirely.
      aria-hidden={!menuOpen}
    >
      <Shell className="nav-top">
        <div className="nav-brand">
          <Icon name="logo" />
          <span>Lumora</span>
        </div>
        <button type="button" className="nav-close" onClick={closeMenu}>
          <Icon name="x" />
          <span>Close</span>
        </button>
      </Shell>

      <Shell as="nav" className="nav-body" aria-label="Menu">
        <ul>
          {NAV_ITEMS.map((item, index) => (
            <li key={item.label}>
              <button
                type="button"
                className="nav-item"
                onClick={() => handleNavClick(item)}
                // Staggered inline so items cascade in as the overlay opens.
                // CSS handles the motion; only the offset varies per item.
                style={{ transitionDelay: `${index * 45 + 80}ms` }}
              >
                <span className="n">0{index + 1}</span>
                <span className="l">{item.label}</span>
              </button>
            </li>
          ))}
        </ul>
      </Shell>

      <Shell className="nav-bottom">
        <span>Local time — {time}</span>
        <button
          type="button"
          className="nav-start"
          onClick={() => closeMenuThen(openModal)}
        >
          Start a project →
        </button>
      </Shell>
    </div>
  );
}
