/**
 * Hero "liquid reveal" — painting a second image along the cursor trail.
 *
 * ── The trick ───────────────────────────────────────────────────────────────
 * Two images are stacked. The "base" is an ordinary <img>. The "brush" image is
 * drawn to a canvas on top, but only where the cursor has recently been.
 *
 * Per frame:
 *   1. Fade the whole canvas slightly, using `destination-out` composition —
 *      this subtracts alpha rather than painting grey over it, so what fades
 *      out reveals the base image beneath instead of dimming toward black.
 *   2. Stamp the brush image at each new pointer position, masked by a radial
 *      gradient (`source-in`) so each dab has soft edges.
 *
 * The result reads as liquid because the fade and the stamps overlap
 * continuously rather than running as discrete animations.
 * ───────────────────────────────────────────────────────────────────────────
 *
 * Skipped entirely when the visitor prefers reduced motion.
 *
 * @param {import('react').RefObject<HTMLElement>} containerRef Sized element
 * @param {import('react').RefObject<HTMLCanvasElement>} canvasRef
 * @param {string} imageSrc Image to paint along the trail
 */

import { useEffect } from 'react';
import { BRUSH_RADIUS, DECAY, FADE_FRAMES, REDUCED } from '../config/constants.js';

export function useLiquidReveal(containerRef, canvasRef, imageSrc) {
  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;

    if (!container || !canvas || REDUCED) return undefined;

    const context = canvas.getContext('2d');
    if (!context) return undefined;

    // Cap at 2: beyond that the pixel cost climbs fast for no visible gain.
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const radius = BRUSH_RADIUS * dpr;
    const diameter = Math.ceil(radius * 2);

    // Offscreen buffer holding the brush image scaled to cover the container.
    // Rescaling it per stamp instead would be ruinously expensive.
    const cover = document.createElement('canvas');
    const coverContext = cover.getContext('2d');

    // Scratch buffer where each dab is masked before being composited.
    const brush = document.createElement('canvas');
    brush.width = diameter;
    brush.height = diameter;
    const brushContext = brush.getContext('2d');

    let width = 0;
    let height = 0;
    let loaded = false;
    let frameId = null;

    const points = [];
    let lastPoint = null;
    let idleFrames = 0;

    /** Redraws the cover buffer, scaling the image to fill (object-fit: cover). */
    function drawCover() {
      if (!loaded || !width || !height) return;

      cover.width = width;
      cover.height = height;

      const scale = Math.max(width / image.width, height / image.height);
      const scaledWidth = image.width * scale;
      const scaledHeight = image.height * scale;

      coverContext.clearRect(0, 0, width, height);
      coverContext.drawImage(
        image,
        (width - scaledWidth) / 2,
        (height - scaledHeight) / 2,
        scaledWidth,
        scaledHeight,
      );
    }

    /** Matches the canvas backing store to the container's CSS size × dpr. */
    function resize() {
      const rect = container.getBoundingClientRect();
      if (!rect.width || !rect.height) return;

      width = Math.round(rect.width * dpr);
      height = Math.round(rect.height * dpr);

      // Backing store in device pixels, display size in CSS pixels — this is
      // what keeps the result sharp on high-DPI screens.
      canvas.width = width;
      canvas.height = height;
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;

      drawCover();

      // Any existing trail is now at the wrong scale.
      context.clearRect(0, 0, width, height);
      points.length = 0;
      lastPoint = null;
    }

    const image = new Image();
    // The image ships with the bundle, so it is same-origin and the canvas is
    // never tainted. (A remote source would need image.crossOrigin here.)
    image.onload = () => {
      loaded = true;
      resize();
    };
    image.src = imageSrc;

    /** Stamps one soft-edged dab of the brush image at (x, y). */
    function stamp(x, y) {
      const centre = radius;

      brushContext.clearRect(0, 0, diameter, diameter);

      // 1. Paint the alpha mask: opaque at the centre, transparent at the rim.
      brushContext.globalCompositeOperation = 'source-over';
      const gradient = brushContext.createRadialGradient(
        centre,
        centre,
        0,
        centre,
        centre,
        radius,
      );
      gradient.addColorStop(0, 'rgba(255,255,255,1)');
      // The mid stop holds the dab's core solid, so overlapping stamps along a
      // fast drag build a continuous stroke rather than a string of blobs.
      gradient.addColorStop(0.55, 'rgba(255,255,255,0.82)');
      gradient.addColorStop(1, 'rgba(255,255,255,0)');
      brushContext.fillStyle = gradient;
      brushContext.fillRect(0, 0, diameter, diameter);

      // 2. `source-in` keeps the incoming image only where the mask is opaque.
      brushContext.globalCompositeOperation = 'source-in';
      brushContext.drawImage(
        cover,
        x - centre,
        y - centre,
        diameter,
        diameter,
        0,
        0,
        diameter,
        diameter,
      );

      // 3. Composite the finished dab onto the visible canvas.
      context.globalCompositeOperation = 'source-over';
      context.drawImage(brush, x - centre, y - centre);
    }

    function onPointerMove(event) {
      if (!loaded || !width) return;

      const rect = container.getBoundingClientRect();
      const x = (event.clientX - rect.left) * dpr;
      const y = (event.clientY - rect.top) * dpr;

      // Outside the hero (plus a brush-width margin): break the stroke so
      // re-entering elsewhere doesn't draw a line across the whole image.
      if (x < -radius || y < -radius || x > width + radius || y > height + radius) {
        lastPoint = null;
        return;
      }

      if (lastPoint) {
        // Pointer events arrive far apart during a fast drag. Interpolate
        // between them, otherwise the stroke breaks into disconnected dabs.
        const dx = x - lastPoint.x;
        const dy = y - lastPoint.y;
        const distance = Math.hypot(dx, dy);
        const stepSize = Math.max(radius * 0.3, 1);
        // Capped so one enormous jump can't queue thousands of stamps.
        const steps = Math.min(Math.ceil(distance / stepSize), 60);

        for (let i = 1; i <= steps; i += 1) {
          points.push({
            x: lastPoint.x + dx * (i / steps),
            y: lastPoint.y + dy * (i / steps),
          });
        }
      } else {
        points.push({ x, y });
      }

      lastPoint = { x, y };
    }

    function tick() {
      frameId = requestAnimationFrame(tick);
      if (!loaded || !width) return;

      const drawing = points.length > 0;

      if (drawing) {
        idleFrames = 0;
      } else {
        idleFrames += 1;
        if (idleFrames > FADE_FRAMES) {
          // Clear once on the first frame past the threshold, then idle without
          // touching the canvas at all until the cursor returns.
          if (idleFrames === FADE_FRAMES + 1) context.clearRect(0, 0, width, height);
          return;
        }
      }

      // Fade accelerates the longer the cursor sits still, so an abandoned
      // trail dissolves rather than lingering at a constant rate.
      const fade = drawing ? DECAY : Math.min(DECAY + idleFrames * 0.004, 0.5);

      // `destination-out` subtracts alpha — the colour here is irrelevant,
      // only its alpha channel matters.
      context.globalCompositeOperation = 'destination-out';
      context.fillStyle = `rgba(0,0,0,${fade})`;
      context.fillRect(0, 0, width, height);

      if (drawing) {
        for (let i = 0; i < points.length; i += 1) {
          stamp(points[i].x, points[i].y);
        }
        points.length = 0;
      }
    }

    // Listen on window, not the canvas: the canvas is pointer-events:none, and
    // the hero's own content sits on top of it.
    window.addEventListener('pointermove', onPointerMove, { passive: true });

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(container);
    resize();

    frameId = requestAnimationFrame(tick);

    return () => {
      if (frameId !== null) cancelAnimationFrame(frameId);
      window.removeEventListener('pointermove', onPointerMove);
      resizeObserver.disconnect();
      // Stop a late decode from calling resize() after teardown.
      image.onload = null;
    };
  }, [containerRef, canvasRef, imageSrc]);
}
