/**
 * Paragraph reveal — words rise into place one after another.
 *
 * Takes `segments` so a sentence can carry mixed styling while the stagger
 * still runs continuously across the whole thing:
 *
 *   <RevealWords segments={[
 *     { text: 'We partner with ambitious teams to ship' },
 *     { text: 'digital products…', className: 'muted' },
 *   ]} />
 *
 * Unlike lines, words wrap naturally — each `.word` is inline-block, so the
 * browser still decides where the text breaks.
 *
 * Replaces the original `splitWords()`, which mutated the DOM by walking text
 * nodes and swapping in fragments after render.
 *
 * @param {{ text: string, className?: string }[]} props.segments
 * @param {number} [props.stagger] ms between consecutive words.
 */

import { useReveal } from '../../hooks/useReveal.js';
import { DURATION, EASE_WORD } from '../../config/easings.js';

export default function RevealWords({
  as: Tag = 'h2',
  segments = [],
  delay = 0,
  stagger = 35,
  duration = DURATION.word,
  gate = false,
  className,
  ...rest
}) {
  const [ref, played] = useReveal({ gate });

  // Runs across every segment so the stagger doesn't restart at each style
  // change — the sentence reads as one continuous motion.
  let wordIndex = 0;

  return (
    <Tag ref={ref} className={className} {...rest}>
      {segments.map((segment, segmentIndex) => {
        const words = segment.text.trim().split(/\s+/);

        return (
          <span className={segment.className} key={segmentIndex}>
            {/* Space between segments; without it "ship" and "digital" collide. */}
            {segmentIndex > 0 && ' '}
            {words.map((word, index) => {
              const wordDelay = delay + wordIndex * stagger;
              wordIndex += 1;

              return (
                <span key={index}>
                  <span className="word">
                    <span
                      className="word-i"
                      style={{
                        transform: played ? 'translateY(0)' : 'translateY(24px)',
                        opacity: played ? 1 : 0,
                        transition:
                          `transform ${duration}ms ${EASE_WORD} ${wordDelay}ms, ` +
                          `opacity ${duration}ms ${EASE_WORD} ${wordDelay}ms`,
                      }}
                    >
                      {word}
                    </span>
                  </span>
                  {/* Outside the mask, so the gap isn't clipped along with the word. */}
                  {index < words.length - 1 && ' '}
                </span>
              );
            })}
          </span>
        );
      })}
    </Tag>
  );
}
