/**
 * Application root — providers and page composition.
 *
 * Provider order matters. ScrollProvider is outermost because both overlays
 * lock scrolling through it. IntroProvider sits inside it and is read by every
 * gated reveal. UIProvider is innermost, holding only overlay open/closed
 * state.
 */

import { useCallback } from 'react';
import { ScrollProvider } from './context/ScrollProvider.jsx';
import { IntroProvider, useIntro } from './context/IntroProvider.jsx';
import { UIProvider } from './context/UIProvider.jsx';

import SkipLink from './components/common/SkipLink.jsx';
import Loader from './components/layout/Loader.jsx';
import Header from './components/layout/Header.jsx';
import NavMenu from './components/layout/NavMenu.jsx';
import Footer from './components/layout/Footer.jsx';

import Hero from './components/sections/Hero.jsx';
import About from './components/sections/About.jsx';
import CreateBand from './components/sections/CreateBand.jsx';
import Works from './components/sections/Works.jsx';
import Services from './components/sections/Services.jsx';
import Stats from './components/sections/Stats.jsx';

import RequestModal from './features/contact/RequestModal.jsx';

import { useAdaptiveGrid } from './hooks/useAdaptiveGrid.js';

/**
 * Split out from App so it can call useIntro — a component cannot consume a
 * context that it renders the provider for.
 */
function Page() {
  const { markIntroReady } = useIntro();

  // Releases the reveal gate as the loader slides away.
  const handleLoaderExit = useCallback(() => markIntroReady(), [markIntroReady]);

  return (
    <>
      <SkipLink />
      <Loader onExit={handleLoaderExit} />

      <Header />

      <main id="main">
        <Hero />
        <About />
        <CreateBand />
        <Works />
        <Services />
        <Stats />
      </main>

      <Footer />

      {/* Overlays render last so they stack above the page without needing
          higher z-index values than the design already sets. */}
      <NavMenu />
      <RequestModal />
    </>
  );
}

export default function App() {
  // Scales the root font size on viewports wider than the 1920px baseline.
  useAdaptiveGrid();

  return (
    <ScrollProvider>
      <IntroProvider>
        <UIProvider>
          <Page />
        </UIProvider>
      </IntroProvider>
    </ScrollProvider>
  );
}
