/**
 * An element animated by a hover spring.
 *
 * Thin wrapper over useSpringHover so markup stays declarative:
 *
 *   <SpringHover className="pill-scale" to={{ scale: 1.04 }}>…</SpringHover>
 *
 * Animatable keys: x, y (px), scale, rotate (deg), opacity, pl, pr (rem), bg.
 *
 * @param {object}   props
 * @param {string}  [props.as]       Element to render. Default 'span'.
 * @param {number}  [props.tension]
 * @param {number}  [props.friction]
 * @param {object}  [props.from]     Resting values. Omitted keys use the defaults.
 * @param {object}  [props.to]       Hovered values.
 */

import { useSpringHover } from '../../hooks/useSpringHover.js';

export default function SpringHover({
  as: Tag = 'span',
  tension = 320,
  friction = 18,
  from,
  to,
  className,
  children,
  ...rest
}) {
  const ref = useSpringHover({ tension, friction, from, to });

  return (
    // `hv` marks spring-driven elements. A few CSS rules target it for layout
    // (.menu-btn .hv sets the button's padding, for one).
    <Tag ref={ref} className={className ? `hv ${className}` : 'hv'} {...rest}>
      {children}
    </Tag>
  );
}
