/**
 * Tunable constants for the animation systems.
 *
 * Everything here was a magic number in the original single-file script.
 */

/* --- Hero imagery --------------------------------------------------------
   Imported rather than fetched from a URL, so Vite fingerprints the files,
   emits them into the build, and fails loudly at build time if one is missing.
   Being same-origin also means the canvas is never tainted, so the brush image
   can be read back and composited freely.
   ------------------------------------------------------------------------- */

import baseImage from '../assets/after.jpg';
import brushImage from '../assets/before.jpg';

export const HERO_IMAGES = {
  /** Rendered as a plain <img>; what you see before the cursor touches it. */
  base: baseImage,
  /** Painted onto the canvas along the cursor trail. */
  brush: brushImage,
};

/* --- Adaptive grid ------------------------------------------------------- */

/** Design baseline: 1rem = 16px at a 1920px-wide viewport. */
export const FONT_BASE = 16;
export const GRID_BASE_WIDTH = 1920;
/** How aggressively the root font size tracks viewport width. */
export const GRID_COEF = 0.6666;

/* --- Loader -------------------------------------------------------------- */

/** How long the progress bar takes to sweep 0 -> 100. */
export const FILL_MS = 1300;
/** Fallback in case the loader's transitionend never fires (background tabs). */
export const LOADER_EXIT_TIMEOUT_MS = 1100;
/** Last-resort ungate: never leave the page locked and blank. */
export const INTRO_SAFETY_MS = 5000;

/* --- Liquid reveal (hero canvas) ----------------------------------------- */

/** Brush radius in CSS pixels, scaled by devicePixelRatio at use time. */
export const BRUSH_RADIUS = 143;
/** Alpha removed per frame while painting — controls how fast the trail fades. */
export const DECAY = 0.016;
/** Idle frames before the canvas is cleared outright (~2s at 60fps). */
export const FADE_FRAMES = 120;

/* --- Media queries -------------------------------------------------------
   Read once at module load. These describe hardware and OS settings that do
   not change during a session, so there is no listener to maintain.
   ------------------------------------------------------------------------- */

/** True when the visitor asked for reduced motion. */
export const REDUCED =
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/** True for mouse/trackpad. False on touch, where hover states never resolve. */
export const CAN_HOVER =
  typeof window !== 'undefined' &&
  window.matchMedia('(hover:hover) and (pointer:fine)').matches;
