/**
 * Overlay state: the nav menu and the contact modal.
 *
 * Lives in context because both are opened from several unrelated places — the
 * header button, hero CTAs, footer CTA, and the nav overlay's own footer link.
 * Prop-drilling `openModal` through six levels of section components would be
 * the alternative.
 */

import { createContext, useCallback, useContext, useMemo, useState } from 'react';

const UIContext = createContext(null);

/**
 * The nav overlay takes ~460ms to fade out. Opening the modal immediately would
 * stack the two panels; this delay lets the menu clear first.
 */
const MENU_TO_MODAL_DELAY = 260;

export function UIProvider({ children }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);

  const openMenu = useCallback(() => setMenuOpen(true), []);
  const closeMenu = useCallback(() => setMenuOpen(false), []);

  const openModal = useCallback(() => setModalOpen(true), []);
  const closeModal = useCallback(() => setModalOpen(false), []);

  /**
   * Closes the menu, then runs `action` once it has visually cleared.
   * Used for both "Contact" (opens the modal) and section links (scroll).
   */
  const closeMenuThen = useCallback((action) => {
    setMenuOpen(false);
    setTimeout(action, MENU_TO_MODAL_DELAY);
  }, []);

  const value = useMemo(
    () => ({
      menuOpen,
      openMenu,
      closeMenu,
      closeMenuThen,
      modalOpen,
      openModal,
      closeModal,
    }),
    [menuOpen, openMenu, closeMenu, closeMenuThen, modalOpen, openModal, closeModal],
  );

  return <UIContext.Provider value={value}>{children}</UIContext.Provider>;
}

export function useUI() {
  const context = useContext(UIContext);
  if (!context) throw new Error('useUI must be used within <UIProvider>');
  return context;
}
