/**
 * "Start a project" modal.
 *
 * Owns the dialog shell, its open/close choreography, and the swap from form to
 * confirmation. The form itself lives in RequestForm.
 *
 * Visibility follows the same two-stage pattern as NavMenu — display first,
 * then the transition class on the next frame — with one addition: a `.closing`
 * state, so the panel can leave along a shorter path than it entered on.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import Pill from '../../components/common/Pill.jsx';
import Icon from '../../components/icons/Icon.jsx';
import RequestForm from './RequestForm.jsx';
import { useUI } from '../../context/UIProvider.jsx';
import { useScrollLock } from '../../context/ScrollProvider.jsx';
import { useEscapeKey } from '../../hooks/useEscapeKey.js';
import '../../styles/components/modal.css';

/** Must match the panel transition in modal.css (0.6s + slack). */
const CLOSE_MS = 520;

/** Extra beat before resetting content, so the reset isn't visible mid-close. */
const RESET_DELAY_MS = 300;

export default function RequestModal() {
  const { modalOpen, closeModal } = useUI();

  const [mounted, setMounted] = useState(false); // drives `display`
  const [open, setOpen] = useState(false); // drives the entrance
  const [closing, setClosing] = useState(false); // drives the exit
  const [submitted, setSubmitted] = useState(false);

  const framesRef = useRef([]);

  useScrollLock(modalOpen);
  useEscapeKey(modalOpen, closeModal);

  useEffect(() => {
    framesRef.current.forEach(cancelAnimationFrame);
    framesRef.current = [];

    if (modalOpen) {
      setMounted(true);
      setClosing(false);

      const outer = requestAnimationFrame(() => {
        const inner = requestAnimationFrame(() => setOpen(true));
        framesRef.current.push(inner);
      });
      framesRef.current.push(outer);

      return () => {
        framesRef.current.forEach(cancelAnimationFrame);
        framesRef.current = [];
      };
    }

    setOpen(false);
    setClosing(true);

    const hideTimer = setTimeout(() => {
      setMounted(false);
      setClosing(false);
    }, CLOSE_MS);

    // Reset only after the panel is out of sight — otherwise the visitor
    // watches the confirmation flip back to an empty form as it closes.
    const resetTimer = setTimeout(() => setSubmitted(false), CLOSE_MS + RESET_DELAY_MS);

    return () => {
      clearTimeout(hideTimer);
      clearTimeout(resetTimer);
    };
  }, [modalOpen]);

  const handleSuccess = useCallback(() => setSubmitted(true), []);

  /** Clicking the backdrop closes; clicking inside the panel must not. */
  function handleBackdropClick(event) {
    if (event.target === event.currentTarget) closeModal();
  }

  const modalClasses = [open && 'open', closing && 'closing'].filter(Boolean).join(' ');

  return (
    <div
      id="modal"
      className={modalClasses || undefined}
      style={{ display: mounted ? 'flex' : 'none' }}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
      aria-hidden={!modalOpen}
      onClick={handleBackdropClick}
    >
      <div className={submitted ? 'modal-panel done' : 'modal-panel'}>
        <button type="button" className="modal-close" onClick={closeModal} aria-label="Close">
          <Icon name="x" />
        </button>

        {/* Both panels stay mounted; `.done` on the parent decides which is
            displayed. Keeps the CSS identical to the original. */}
        <div className="modal-default">
          <div className="modal-head">
            <span className="modal-kicker">Start a project</span>
            <h2 id="modal-title">Tell us what you&apos;re building.</h2>
          </div>
          <RequestForm onSuccess={handleSuccess} />
        </div>

        <div className="modal-success">
          <div className="badge">
            <Icon name="logo" />
          </div>
          <h2>Request received</h2>
          <p>
            Thanks for reaching out — we&apos;ll get back to you within one business day.
          </p>
          <Pill variant="dark" onClick={closeModal}>
            Close
          </Pill>
        </div>
      </div>
    </div>
  );
}
