/**
 * Hero section.
 *
 * Every reveal here is gated on the loader: this content is on screen from the
 * first frame, so ungated it would animate behind the loader and already be
 * settled by the time anyone saw it. The `delay` values then choreograph the
 * order once the gate opens — eyebrow, headline, rating, CTAs, card, partners,
 * status bar.
 */

import Shell from '../common/Shell.jsx';
import Eyebrow from '../common/Eyebrow.jsx';
import Pill from '../common/Pill.jsx';
import Reveal from '../reveal/Reveal.jsx';
import RevealLines from '../reveal/RevealLines.jsx';
import Icon from '../icons/Icon.jsx';
import LiquidCanvas from './LiquidCanvas.jsx';
import HeroCard from './HeroCard.jsx';
import Partners from './Partners.jsx';
import { useScroll } from '../../context/ScrollProvider.jsx';
import { useUI } from '../../context/UIProvider.jsx';
import '../../styles/components/hero.css';

export default function Hero() {
  const { scrollToId } = useScroll();
  const { openModal } = useUI();

  return (
    <section id="home">
      <LiquidCanvas />

      {/* Gradient scrim keeping the dark text legible over the photograph. */}
      <div className="hero-vignette" />

      <Reveal
        className="hero-watermark"
        offsets={{ y: 20, o: 0 }}
        // Rests semi-transparent rather than fully opaque — it sits behind the
        // headline and must not compete with it.
        finalOpacity={0.4}
        delay={300}
        duration={900}
        gate
      >
        LUMORA
      </Reveal>

      <Shell className="hero-grid">
        <div className="hero-left">
          <Reveal offsets={{ y: 10, o: 0 }} delay={200} duration={700} gate>
            <Eyebrow>Independent Studio</Eyebrow>
          </Reveal>

          <RevealLines
            as="h1"
            className="hero-h1"
            delay={250}
            stagger={120}
            gate
            lines={['Bold ideas,', 'shipped with', 'quiet precision']}
          />

          <Reveal className="hero-rating" offsets={{ y: 10, o: 0 }} delay={650} duration={700} gate>
            {/* Decorative: the rating is stated in the text beside it. */}
            <span className="hero-stars" aria-hidden="true">
              {Array.from({ length: 5 }, (_, i) => (
                <Icon name="star" key={i} />
              ))}
            </span>
            <span className="hero-rating-text">200+ brands shipped</span>
          </Reveal>

          <Reveal className="hero-ctas" offsets={{ y: 10, o: 0 }} delay={750} duration={700} gate>
            <Pill variant="dark" arrow="right" onClick={openModal}>
              Let&apos;s Talk
            </Pill>
            <Pill variant="outline" onClick={() => scrollToId('works')}>
              View Work
            </Pill>
          </Reveal>
        </div>

        <div className="hero-right">
          <HeroCard />
          <Partners />
        </div>
      </Shell>

      <Reveal className="hero-status" offsets={{ o: 0 }} delay={900} duration={800} gate>
        <span>Working since 2014</span>
        <span className="mid">Remote-first, worldwide</span>
        <span className="end">
          Scroll to explore <span aria-hidden="true">↓</span>
        </span>
      </Reveal>
    </section>
  );
}
