/**
 * Site footer — closing CTA, link columns, legal row, and the giant wordmark.
 */

import Shell from '../common/Shell.jsx';
import Pill from '../common/Pill.jsx';
import HoverGroup from '../common/HoverGroup.jsx';
import SpringHover from '../common/SpringHover.jsx';
import RevealLines from '../reveal/RevealLines.jsx';
import Icon from '../icons/Icon.jsx';
import {
  FOOTER_BRAND,
  FOOTER_COLUMNS,
  LEGAL_LINKS,
} from '../../data/footerColumns.js';
import { useUI } from '../../context/UIProvider.jsx';
import '../../styles/components/footer.css';

/** Shared hover spring for footer links: slide right and brighten. */
const LINK_SPRING = {
  tension: 320,
  friction: 22,
  from: { x: 0, opacity: 0.65 },
  to: { x: 4, opacity: 1 },
};

export default function Footer() {
  const { openModal } = useUI();

  return (
    <footer>
      <Shell className="footer-inner">
        <div className="footer-cta">
          <RevealLines
            className="footer-h2"
            stagger={100}
            lines={['Have a project', "in mind? Let's", 'get to work.']}
          />
          <Pill variant="light" arrow="up-right" onClick={openModal}>
            Start a project
          </Pill>
        </div>

        <div className="footer-cols">
          {/* Brand column sits outside the data-driven columns — it's the only
              one with a logo and tagline rather than a link list. */}
          <div className="footer-col">
            <div className="footer-brand">
              <Icon name="logo" />
              <span>{FOOTER_BRAND.name}</span>
            </div>
            <p className="footer-tag">{FOOTER_BRAND.tagline}</p>
          </div>

          {FOOTER_COLUMNS.map((column) => (
            <div className="footer-col" key={column.title}>
              <h3>{column.title}</h3>
              <ul>
                {column.links.map((link) => (
                  <li key={link.label}>
                    <HoverGroup as="a" className="alink" href={link.href}>
                      <SpringHover {...LINK_SPRING}>{link.label}</SpringHover>
                    </HoverGroup>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        <div className="footer-legal">
          <p>{FOOTER_BRAND.copyright}</p>
          <div className="footer-legal-links">
            {LEGAL_LINKS.map((link) => (
              <HoverGroup as="a" className="alink" href={link.href} key={link.label}>
                <SpringHover
                  tension={320}
                  friction={22}
                  from={{ x: 0, opacity: 0.7 }}
                  to={{ x: 3, opacity: 1 }}
                >
                  {link.label}
                </SpringHover>
              </HoverGroup>
            ))}
          </div>
        </div>
      </Shell>

      {/* Decorative wordmark, clipped by the footer's overflow:hidden. */}
      <div className="footer-wm" aria-hidden="true">
        LUMORA
      </div>
    </footer>
  );
}
