/**
 * Spring-physics hover animation.
 *
 * Ports the original `initHovers()` engine, which scanned the DOM for
 * `[data-spring]` attributes. Here a component asks for a spring directly and
 * gets back a ref to attach.
 *
 * ── How it works ────────────────────────────────────────────────────────────
 * A single scalar `t` is integrated from 0 (resting) to 1 (hovered) by a
 * damped spring. Every animated property is then a straight interpolation
 * between its `from` and `to` value at that `t`. One spring drives any number
 * of properties, so they can never drift out of sync.
 *
 * Styles are written straight to the DOM node rather than through React state:
 * this runs at 60fps and must not trigger a re-render per frame.
 *
 * ── Hover groups ────────────────────────────────────────────────────────────
 * Hovering one card often animates several nested pieces at once — the card
 * lifts, its badge rotates, its arrow slides. Wrapping them in a <HoverGroup>
 * makes one pointer event drive them all. Without a group, the element listens
 * to its own pointer events.
 * ───────────────────────────────────────────────────────────────────────────
 */

import { useContext, useEffect, useRef } from 'react';
import { HoverGroupContext } from '../components/common/HoverGroup.jsx';
import { CAN_HOVER } from '../config/constants.js';

/** Resting value for each animatable property. */
const SPRING_BASE = {
  x: 0,
  y: 0,
  scale: 1,
  rotate: 0,
  opacity: 1,
  pl: 0, // padding-left, in rem
  pr: 0, // padding-right, in rem
  bg: 0, // background alpha over the --surface colour
};

/** Fixed timestep. Assumes ~60fps; ties animation speed to frame rate. */
const DT = 1 / 60;

/** Below both thresholds the spring is close enough — snap and stop the loop. */
const REST_THRESHOLD = 0.001;

/**
 * @param {object} config
 * @param {number} [config.tension]  Stiffness. Higher = snappier.
 * @param {number} [config.friction] Damping. Higher = less overshoot.
 * @param {object} [config.from]     Property values at rest. Defaults to SPRING_BASE.
 * @param {object} [config.to]       Property values when hovered.
 * @param {boolean} [config.disabled]
 * @returns {import('react').RefObject<HTMLElement>} Ref to attach to the animated element
 */
export function useSpringHover({
  tension = 320,
  friction = 18,
  from = null,
  to = null,
  disabled = false,
} = {}) {
  const elementRef = useRef(null);
  const group = useContext(HoverGroupContext);

  // `from`/`to` are almost always inline object literals, so their identity
  // changes every render. Comparing serialised content keeps the effect from
  // tearing down and rebuilding the spring on each one.
  const configKey = JSON.stringify({ tension, friction, from, to, disabled });

  useEffect(() => {
    const element = elementRef.current;

    // Touch devices have no hover state to leave — a spring there would latch
    // on first tap and never release.
    if (!element || disabled || !CAN_HOVER) return undefined;

    const fromValues = from || {};
    const toValues = to || {};
    const keys = Array.from(
      new Set([...Object.keys(fromValues), ...Object.keys(toValues)]),
    );
    if (keys.length === 0) return undefined;

    // Spring state: position, velocity, and where we're heading.
    let position = 0;
    let velocity = 0;
    let target = 0;
    let frameId = null;

    /** Interpolates one property at progress `t`. */
    const valueAt = (key, t) => {
      const start = fromValues[key] !== undefined ? fromValues[key] : SPRING_BASE[key];
      const end = toValues[key] !== undefined ? toValues[key] : SPRING_BASE[key];
      return start + (end - start) * t;
    };

    /** Writes the interpolated values for progress `t` onto the element. */
    function apply(t) {
      let transform = '';

      // x and y share one translate(), so requesting either emits both.
      if (keys.includes('x') || keys.includes('y')) {
        transform += `translate(${valueAt('x', t).toFixed(3)}px,${valueAt('y', t).toFixed(3)}px)`;
      }
      if (keys.includes('scale')) {
        transform += ` scale(${valueAt('scale', t).toFixed(4)})`;
      }
      if (keys.includes('rotate')) {
        transform += ` rotate(${valueAt('rotate', t).toFixed(3)}deg)`;
      }
      if (transform) element.style.transform = transform;

      if (keys.includes('opacity')) {
        element.style.opacity = valueAt('opacity', t).toFixed(3);
      }
      // Used by the services rows, which widen their padding on hover.
      if (keys.includes('pl')) {
        element.style.paddingLeft = `${valueAt('pl', t).toFixed(4)}rem`;
      }
      if (keys.includes('pr')) {
        element.style.paddingRight = `${valueAt('pr', t).toFixed(4)}rem`;
      }
      // `bg` fades in the --surface colour rather than swapping it, so the row
      // background can animate alongside the padding.
      if (keys.includes('bg')) {
        element.style.backgroundColor = `rgba(241,240,238,${valueAt('bg', t).toFixed(3)})`;
      }
    }

    function step() {
      // F = -k·x - c·v, with mass = 1 so acceleration equals force.
      const acceleration = tension * (target - position) - friction * velocity;
      velocity += acceleration * DT;
      position += velocity * DT;

      // Settled: snap exactly onto the target and stop burning frames.
      if (
        Math.abs(target - position) < REST_THRESHOLD &&
        Math.abs(velocity) < REST_THRESHOLD
      ) {
        position = target;
        velocity = 0;
        apply(position);
        frameId = null;
        return;
      }

      apply(position);
      frameId = requestAnimationFrame(step);
    }

    /** Retargets the spring. The loop restarts only if it had settled. */
    function setTarget(next) {
      target = next;
      if (frameId === null) frameId = requestAnimationFrame(step);
    }

    // Paint the resting state immediately — `from` may differ from the CSS
    // defaults (nav links, for instance, start at 80% opacity).
    apply(0);

    let cleanupListeners;

    if (group) {
      // Driven by the enclosing HoverGroup.
      cleanupListeners = group.subscribe((active) => setTarget(active ? 1 : 0));
    } else {
      const onEnter = (event) => {
        // A touch pointer fires pointerenter but never pointerleave.
        if (event.pointerType === 'touch') return;
        setTarget(1);
      };
      const onLeave = () => setTarget(0);
      const onFocusIn = () => setTarget(1);
      const onFocusOut = () => setTarget(0);

      element.addEventListener('pointerenter', onEnter);
      element.addEventListener('pointerleave', onLeave);
      element.addEventListener('focusin', onFocusIn);
      element.addEventListener('focusout', onFocusOut);

      cleanupListeners = () => {
        element.removeEventListener('pointerenter', onEnter);
        element.removeEventListener('pointerleave', onLeave);
        element.removeEventListener('focusin', onFocusIn);
        element.removeEventListener('focusout', onFocusOut);
      };
    }

    return () => {
      // The original never cancelled its rAF — harmless on a page that never
      // unmounts, but a leak in React.
      if (frameId !== null) cancelAnimationFrame(frameId);
      cleanupListeners();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [configKey, group]);

  return elementRef;
}
