/**
 * Broadcasts one hover state to every spring nested inside it.
 *
 * Replaces the original `[data-hgroup]` + `data-trigger="group"` pairing, where
 * each spring called `closest('[data-hgroup]')` to find its trigger. React
 * context gives the same "nearest ancestor wins" semantics without touching the
 * DOM, and nests correctly.
 *
 * Usage:
 *   <HoverGroup as="button" onClick={...}>
 *     <SpringHover to={{ scale: 1.04 }}>…</SpringHover>
 *     <SpringHover to={{ x: 3 }}>…</SpringHover>   ← both animate together
 *   </HoverGroup>
 *
 * Subscribers are notified imperatively rather than through state, so a hover
 * never re-renders the subtree.
 */

import { createContext, useCallback, useMemo, useRef } from 'react';

/** Consumed by useSpringHover. `null` means "no group" — listen to yourself. */
export const HoverGroupContext = createContext(null);

export default function HoverGroup({ as: Tag = 'div', children, ...rest }) {
  const subscribersRef = useRef(new Set());

  const notify = useCallback((active) => {
    subscribersRef.current.forEach((callback) => callback(active));
  }, []);

  const contextValue = useMemo(
    () => ({
      /** @returns {() => void} unsubscribe */
      subscribe(callback) {
        subscribersRef.current.add(callback);
        return () => subscribersRef.current.delete(callback);
      },
    }),
    [],
  );

  const handlers = {
    // pointerenter/leave rather than over/out: they don't fire again as the
    // pointer crosses between child elements.
    onPointerEnter: (event) => {
      // Touch fires enter but never leave, which would strand the spring on.
      if (event.pointerType === 'touch') return;
      notify(true);
    },
    onPointerLeave: () => notify(false),
    // Keyboard parity: focusing anything inside the group animates it too.
    onFocus: () => notify(true),
    onBlur: () => notify(false),
  };

  return (
    <HoverGroupContext.Provider value={contextValue}>
      <Tag {...handlers} {...rest}>
        {children}
      </Tag>
    </HoverGroupContext.Provider>
  );
}
