/**
 * Local time chip in the header.
 *
 * Hidden below 768px — see .clock-chip in header.css.
 */

import { useClock } from '../../hooks/useClock.js';

export default function Clock() {
  const { time, date } = useClock();

  return (
    <div className="clock-chip">
      <span className="clock-label">Local time</span>
      {/* tnum = tabular numerals, so the digits don't shift the layout. */}
      <span className="clock-time tnum">{time}</span>
      <span className="clock-sep">•</span>
      <span className="clock-date">{date}</span>
    </div>
  );
}
