/**
 * Small dotted section label ("Independent Studio", "Portfolio", …).
 *
 * @param {boolean} [props.light] For dark backgrounds.
 * @param {boolean} [props.boxed] Adds a pill outline.
 */

export default function Eyebrow({ light = false, boxed = false, className, children, ...rest }) {
  const classes = ['eyebrow', light && 'light', boxed && 'boxed', className]
    .filter(Boolean)
    .join(' ');

  return (
    <span className={classes} {...rest}>
      {children}
    </span>
  );
}
