/**
 * Scales the root font size on viewports WIDER than the 1920px design baseline.
 *
 * The layout is authored entirely in rem, so changing the root size scales the
 * whole design proportionally. base.css handles everything below 1920px with
 * vw-based media queries; only the scale-up needs JS, because there is no
 * upper-bound media query to express "keep growing past here".
 */

import { useEffect } from 'react';
import { FONT_BASE, GRID_BASE_WIDTH, GRID_COEF } from '../config/constants.js';

export function useAdaptiveGrid() {
  useEffect(() => {
    function apply() {
      const width = window.innerWidth;
      // Negative above the baseline, which is what makes `size` exceed FONT_BASE.
      const widthReduction = ((GRID_BASE_WIDTH - width) / GRID_BASE_WIDTH) * 100;
      const size = FONT_BASE - (FONT_BASE * (widthReduction * GRID_COEF)) / 100;

      if (size > FONT_BASE) {
        document.documentElement.style.fontSize = `${size}px`;
      } else {
        // Remove rather than reset to 16px, so base.css's vw rules take over.
        document.documentElement.style.removeProperty('font-size');
      }
    }

    apply();
    window.addEventListener('resize', apply);

    return () => {
      window.removeEventListener('resize', apply);
      document.documentElement.style.removeProperty('font-size');
    };
  }, []);
}
